#!/bin/bash
# Box 194 (L-NEW successor 62): DATA behind Lemma LOC-GATE and the unconditional OVT-DV (loc194.py). Run from experiments/new/box194.
# inst/ = two L-RED instances (claude/l-red d1a11af6: experiments/red/r217/inst/LEAP_k64.json, experiments/red/r219/inst/rd3_d4.json;
# sha1 = L-RED's SHA1SUMS, copied in inst/SHA1SUMS) and RS2_L{2,4,16,32}M6.json, generated by L-RED's rs2.py «L 6» at claude/l-red
# d1a11af6 (experiments/red/r217/rs2.py + gdsl.py; the same command with L 8 reproduces box193/inst/RS2_L8M6.json, sha1 982d5911).
set -e
cd "$(dirname "$0")"
(cd inst && sha1sum -c --quiet SHA1SUMS) && echo "inst sha1: OK"
python3 loc194.py inst/LEAP_k64.json inst/rd3_d4.json
python3 loc194.py ../box193/inst/CLR_k8s16.json ../box193/inst/FPORT_n2.json ../box193/inst/FPORT_n3.json ../box193/inst/LEAP_k8.json \
  ../box193/inst/RS2.json ../box193/inst/RS2_L8M6.json ../box193/inst/RS3.json ../box193/inst/RSG_K4.json
python3 loc194.py ../box192/inst/cR_d2_w8_R22.json ../box192/inst/rd2_d9.json ../box192/inst/rd2_d10.json ../box192/inst/rd3_d7.json \
  ../box192/inst/rf_d5.json
python3 loc194.py rand 1000 2
python3 quiet194.py inst/rd3_d4.json inst/RS2_L32M6.json ../box193/inst/*.json ../box192/inst/rd2_d9.json ../box192/inst/rd2_d10.json
python3 quiet194.py rand 1000 2
python3 in194.py inst/RS2_L2M6.json inst/RS2_L4M6.json ../box193/inst/RS2_L8M6.json inst/RS2_L16M6.json inst/RS2_L32M6.json
python3 in194.py inst/LEAP_k64.json inst/rd3_d4.json ../box193/inst/*.json ../box192/inst/rd2_d9.json
python3 in194.py rand 300 5
python3 bonly194.py inst/rd3_d4.json inst/RS2_L32M6.json ../box193/inst/*.json ../box192/inst/cR_d2_w8_R22.json ../box192/inst/rd2_d9.json \
  ../box192/inst/rd2_d10.json ../box192/inst/rd3_d7.json ../box192/inst/rf_d5.json
python3 bonly194.py rand 1000 2
